do $$declare d text;begin select pg_get_functiondef('feedx_integrations.business_capability_catalog(uuid)'::regprocedure) into d; d:=replace(d,'''label'',regexp_replace(v->>''label'',''^Preserved '','''')','''label'',coalesce((select r.label from feedx_integrations.resources r where r.key=v->>''resource_key''),regexp_replace(v->>''label'',''^Preserved '',''''))'); d:=replace(d,'jsonb_build_object(''resource'',v->>''resource_key'',''label'',v->>''label'',''scope_note'',v->>''description'')','coalesce((select jsonb_build_object(''resource'',r.slug,''label'',r.label,''scope_note'',r.description,''field_policy'',r.field_policy) from feedx_integrations.resources r where r.key=v->>''resource_key''),jsonb_build_object(''resource'',v->>''resource_key'',''label'',v->>''label'',''scope_note'',v->>''description''))'); execute d;end $$;